from donations import Donation, load_donations, ROWS
from finder import donations_for, has_donor

KEY = ROWS[0][0]
COUNT = sum(1 for k, _ in ROWS if k == KEY)


def test_upper_case_with_spaces():
    assert len(donations_for(list(load_donations()), " " + KEY.upper() + " ")) == COUNT


def test_stored_value_not_tidy():
    data = [Donation("  Alpha", 1), Donation("beta", 2), Donation("ALPHA ", 3)]
    assert [x.pounds for x in donations_for(data, "alpha")] == [1, 3]


def test_exact():
    assert len(donations_for(list(load_donations()), KEY)) == COUNT


def test_no_match():
    assert donations_for(list(load_donations()), "zzz") == [] and not has_donor(list(load_donations()), "zzz")
